CREATE OR REPLACE FUNCTION crm.adicionar_mensagem(p_conversa_id uuid, p_papel text, p_conteudo text, p_canal_message_id text DEFAULT NULL::text, p_tipo_midia text DEFAULT NULL::text, p_midia_url text DEFAULT NULL::text, p_midia_storage_path text DEFAULT NULL::text, p_instagram_media_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_msg_id uuid;
  v_existe uuid;
  v_resumo text;
  v_eh_primeira boolean;
  v_vendedor_user uuid;
BEGIN
  -- dedupe
  IF p_canal_message_id IS NOT NULL THEN
    SELECT id INTO v_existe
    FROM crm.mensagens
    WHERE conversa_id = p_conversa_id AND canal_message_id = p_canal_message_id
    LIMIT 1;
    IF v_existe IS NOT NULL THEN
      -- enriquece se chegou attachment depois
      UPDATE crm.mensagens SET
        midia_url = COALESCE(midia_url, p_midia_url),
        midia_storage_path = COALESCE(midia_storage_path, p_midia_storage_path),
        instagram_media_id = COALESCE(instagram_media_id, p_instagram_media_id)
      WHERE id = v_existe;
      RETURN v_existe;
    END IF;
  END IF;

  -- conta msgs anteriores pra detectar primeira
  SELECT NOT EXISTS (SELECT 1 FROM crm.mensagens WHERE conversa_id = p_conversa_id)
    INTO v_eh_primeira;

  INSERT INTO crm.mensagens (
    conversa_id, papel, conteudo, canal_message_id, tipo_midia,
    midia_url, midia_storage_path, instagram_media_id, metadata
  ) VALUES (
    p_conversa_id, p_papel, p_conteudo, p_canal_message_id, p_tipo_midia,
    p_midia_url, p_midia_storage_path, p_instagram_media_id, COALESCE(p_metadata,'{}'::jsonb)
  )
  RETURNING id INTO v_msg_id;

  v_resumo := substring(COALESCE(p_conteudo, ''), 1, 120);
  IF v_resumo = '' AND p_tipo_midia IS NOT NULL THEN
    v_resumo := '[' || p_tipo_midia || ']';
  END IF;

  -- atualiza conversa
  UPDATE crm.conversas SET
    ultima_msg_em = now(),
    ultima_msg_resumo = v_resumo,
    nao_lidas_count = CASE WHEN p_papel = 'user' THEN nao_lidas_count + 1 ELSE nao_lidas_count END,
    status = CASE WHEN status = 'arquivada' AND p_papel = 'user' THEN 'aberta' ELSE status END
  WHERE id = p_conversa_id;

  -- ciclo de vida: primeira_mensagem
  IF v_eh_primeira THEN
    INSERT INTO crm.ciclo_vida_eventos (conversa_id, contato_id, evento, detalhes)
    SELECT id, contato_id, 'primeira_mensagem', jsonb_build_object('mensagem_id', v_msg_id)
    FROM crm.conversas WHERE id = p_conversa_id;
  END IF;

  -- notificação: se msg do cliente, notifica vendedor responsável
  IF p_papel = 'user' THEN
    SELECT au.id INTO v_vendedor_user
    FROM crm.conversas conv
    JOIN public.vendedores vd ON vd.id_vendedor = conv.vendedor_id
    JOIN auth.users au ON au.id = vd.user_id
    WHERE conv.id = p_conversa_id;

    IF v_vendedor_user IS NOT NULL THEN
      INSERT INTO crm.notificacoes (user_id, tipo, titulo, mensagem, link, conversa_id)
      VALUES (
        v_vendedor_user,
        'mensagem_nova',
        'Nova mensagem',
        v_resumo,
        '/mensageria/' || p_conversa_id::text,
        p_conversa_id
      );
    END IF;
  END IF;

  RETURN v_msg_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_id text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD);
    v_id := COALESCE(v_old->>'id', v_old->>'chave', v_old->>'codigo');
    INSERT INTO crm.audit_log (schema_name, table_name, operacao, registro_id, user_id, dados_antes)
    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'DELETE', v_id, v_user, v_old);
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    v_id := COALESCE(v_new->>'id', v_new->>'chave', v_new->>'codigo');
    INSERT INTO crm.audit_log (schema_name, table_name, operacao, registro_id, user_id, dados_antes, dados_depois)
    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'UPDATE', v_id, v_user, v_old, v_new);
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    v_new := to_jsonb(NEW);
    v_id := COALESCE(v_new->>'id', v_new->>'chave', v_new->>'codigo');
    INSERT INTO crm.audit_log (schema_name, table_name, operacao, registro_id, user_id, dados_depois)
    VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'INSERT', v_id, v_user, v_new);
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION crm.buscar_ou_criar_contato_dm(p_canal text, p_canal_id text, p_nome text, p_username text DEFAULT NULL::text, p_foto_url text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_contato_id bigint;
  v_nome_normalizado text := crm.normalizar_nome(p_nome);
BEGIN
  -- 1) Procura por canal_id (mais preciso)
  SELECT contato_id INTO v_contato_id
  FROM crm.contato_canais
  WHERE canal = p_canal AND canal_id = p_canal_id
  LIMIT 1;
  IF v_contato_id IS NOT NULL THEN
    -- atualiza foto/nome se mudou
    UPDATE crm.contato_canais SET
      foto_url = COALESCE(p_foto_url, foto_url),
      nome_canal = COALESCE(p_nome, nome_canal),
      username = COALESCE(p_username, username)
    WHERE canal = p_canal AND canal_id = p_canal_id;
    RETURN v_contato_id;
  END IF;

  -- 2) Procura por username em outras conexoes (mesmo cliente, canal diferente)
  IF p_username IS NOT NULL AND length(p_username) > 0 THEN
    SELECT contato_id INTO v_contato_id
    FROM crm.contato_canais
    WHERE lower(username) = lower(p_username)
    LIMIT 1;
    IF v_contato_id IS NOT NULL THEN
      INSERT INTO crm.contato_canais (contato_id, canal, canal_id, username, nome_canal, foto_url)
      VALUES (v_contato_id, p_canal, p_canal_id, p_username, p_nome, p_foto_url)
      ON CONFLICT (canal, canal_id) DO NOTHING;
      RETURN v_contato_id;
    END IF;
  END IF;

  -- 3) Procura por nome normalizado em public.contatos
  IF length(v_nome_normalizado) > 3 THEN
    SELECT id_contato INTO v_contato_id
    FROM public.contatos
    WHERE crm.normalizar_nome(nome) = v_nome_normalizado
    LIMIT 1;
    IF v_contato_id IS NOT NULL THEN
      INSERT INTO crm.contato_canais (contato_id, canal, canal_id, username, nome_canal, foto_url)
      VALUES (v_contato_id, p_canal, p_canal_id, p_username, p_nome, p_foto_url)
      ON CONFLICT (canal, canal_id) DO NOTHING;
      RETURN v_contato_id;
    END IF;
  END IF;

  -- 4) Cria novo
  INSERT INTO public.contatos (id_contato, nome, telefone, data_atualizacao)
  VALUES (
    COALESCE((SELECT max(id_contato) FROM public.contatos), 0) + 1,
    p_nome, p_telefone, now()
  )
  RETURNING id_contato INTO v_contato_id;

  INSERT INTO crm.contato_canais (contato_id, canal, canal_id, username, nome_canal, foto_url)
  VALUES (v_contato_id, p_canal, p_canal_id, p_username, p_nome, p_foto_url);

  RETURN v_contato_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.criar_conversa_se_necessario(p_canal text, p_canal_thread_id text, p_canal_contato_id text, p_contato_id bigint)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_conversa_id uuid;
BEGIN
  -- tenta achar conversa por (canal, thread)
  SELECT id INTO v_conversa_id
  FROM crm.conversas
  WHERE canal = p_canal AND canal_thread_id = p_canal_thread_id
  LIMIT 1;

  IF v_conversa_id IS NOT NULL THEN
    -- atualiza contato_id se necessário (merge)
    UPDATE crm.conversas
    SET contato_id = COALESCE(p_contato_id, contato_id)
    WHERE id = v_conversa_id AND (contato_id IS NULL OR contato_id <> p_contato_id);
    RETURN v_conversa_id;
  END IF;

  -- cria nova
  INSERT INTO crm.conversas (canal, canal_thread_id, canal_contato_id, contato_id, status)
  VALUES (p_canal, p_canal_thread_id, p_canal_contato_id, p_contato_id, 'aberta')
  RETURNING id INTO v_conversa_id;

  RETURN v_conversa_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.criar_oportunidade(p_contato_id bigint, p_titulo text, p_funil_id uuid, p_etapa_id uuid DEFAULT NULL::uuid, p_vendedor_id bigint DEFAULT NULL::bigint, p_valor numeric DEFAULT NULL::numeric, p_produto_interesse text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_origem_lead text DEFAULT NULL::text, p_conversa_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_op_id uuid;
  v_etapa_id uuid := p_etapa_id;
  v_etapa_nome text;
BEGIN
  -- Se não informou etapa, pega a primeira do funil
  IF v_etapa_id IS NULL THEN
    SELECT id INTO v_etapa_id FROM crm.funil_etapas
    WHERE funil_id = p_funil_id AND ativo
    ORDER BY ordem LIMIT 1;
  END IF;

  INSERT INTO crm.oportunidades
    (contato_id, vendedor_id, funil_id, etapa_id, titulo, valor,
     produto_interesse, notas, origem_lead, conversa_id)
  VALUES
    (p_contato_id, p_vendedor_id, p_funil_id, v_etapa_id, p_titulo, p_valor,
     p_produto_interesse, p_notas, p_origem_lead, p_conversa_id)
  RETURNING id INTO v_op_id;

  -- Histórico inicial
  SELECT nome INTO v_etapa_nome FROM crm.funil_etapas WHERE id = v_etapa_id;
  INSERT INTO crm.oportunidade_historico
    (oportunidade_id, etapa_nova_id, etapa_nova_nome, user_id)
  VALUES (v_op_id, v_etapa_id, v_etapa_nome, auth.uid());

  RETURN v_op_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.mover_etapa_funil(p_conversa_id uuid, p_etapa_para_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_etapa_de uuid;
  v_user uuid := auth.uid();
BEGIN
  SELECT etapa_atual_id INTO v_etapa_de FROM crm.conversas WHERE id = p_conversa_id;

  INSERT INTO crm.funil_movimentos (conversa_id, etapa_de, etapa_para, motivo, movido_por)
  VALUES (p_conversa_id, v_etapa_de, p_etapa_para_id, p_motivo, v_user);

  UPDATE crm.conversas SET etapa_atual_id = p_etapa_para_id WHERE id = p_conversa_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.mover_oportunidade_etapa(p_oportunidade_id uuid, p_etapa_destino_id uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_etapa_atual_id   uuid;
  v_etapa_atual_nome text;
  v_etapa_destino_nome text;
  v_destino_tipo     text;
BEGIN
  SELECT etapa_id INTO v_etapa_atual_id FROM crm.oportunidades
  WHERE id = p_oportunidade_id FOR UPDATE;

  SELECT nome INTO v_etapa_atual_nome FROM crm.funil_etapas WHERE id = v_etapa_atual_id;
  SELECT nome, tipo INTO v_etapa_destino_nome, v_destino_tipo
  FROM crm.funil_etapas WHERE id = p_etapa_destino_id;

  UPDATE crm.oportunidades
  SET etapa_id = p_etapa_destino_id,
      motivo_perda = CASE WHEN v_destino_tipo = 'perdido' THEN COALESCE(p_motivo, motivo_perda) ELSE motivo_perda END,
      data_entrada_pos_venda = CASE WHEN v_destino_tipo = 'pos_venda' THEN now() ELSE data_entrada_pos_venda END
  WHERE id = p_oportunidade_id;

  INSERT INTO crm.oportunidade_historico
    (oportunidade_id, etapa_anterior_id, etapa_anterior_nome,
     etapa_nova_id, etapa_nova_nome, motivo, user_id)
  VALUES
    (p_oportunidade_id, v_etapa_atual_id, v_etapa_atual_nome,
     p_etapa_destino_id, v_etapa_destino_nome, p_motivo, auth.uid());
END;
$function$

CREATE OR REPLACE FUNCTION crm.normalizar_nome(p_nome text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_nome IS NULL OR length(trim(p_nome)) = 0 THEN RETURN ''; END IF;
  RETURN regexp_replace(lower(unaccent(p_nome)), '[^a-z0-9]', '', 'g');
END;
$function$

CREATE OR REPLACE FUNCTION crm.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION directus.calc_peso_ourofino()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.peso_ouro18 IS NOT NULL AND NEW.fator IS NOT NULL THEN
    NEW.peso_ourofino := ROUND(NEW.peso_ouro18 * NEW.fator, 2);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION directus.fn_atualizar_conclusao_universal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    nome_coluna text := TG_ARGV[0];
    id_concluido text := TG_ARGV[1];
    valor_novo text := (to_jsonb(NEW)->>nome_coluna);
BEGIN
    -- CASO 1: Registro Novo (INSERT)
    IF (TG_OP = 'INSERT') THEN
        IF valor_novo = id_concluido THEN
            NEW.data_conclusao := CURRENT_TIMESTAMP;
        END IF;

    -- CASO 2: Atualização (UPDATE)
    ELSIF (TG_OP = 'UPDATE') THEN
        IF valor_novo = id_concluido AND (to_jsonb(OLD)->>nome_coluna IS DISTINCT FROM id_concluido) THEN
            NEW.data_conclusao := CURRENT_TIMESTAMP;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION directus.fn_ordens_comentarios_update_date_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Se o nome da coluna for diferente de 'updated_at', mude aqui:
    NEW.date_updated = NOW(); 
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION directus.func_gerar_numero_ordem()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    prox_valor INTEGER;
BEGIN
    -- Busca o próximo valor da sequência
    prox_valor := nextval('directus.seq_ordens_estoque_num');

    -- Formata para 'c-' seguido do número preenchido com zeros (ex: 0005)
    -- O número '4' no lpad indica o total de dígitos numéricos desejados
    NEW.numero_ordem := 'c-' || lpad(prox_valor::text, 4, '0');

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION directus.preencher_numero_ordem()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
    next_id INTEGER;
BEGIN
    -- Se o campo vier vazio, geramos o código
    IF NEW.numero_ordem IS NULL THEN
        -- Pega o próximo número da sequência
        next_id := nextval('directus.seq_ordens_numero');
        
        -- Formata: 'C - 0001', 'C - 0002', etc.
        NEW.numero_ordem := 'C-' || TO_CHAR(next_id, 'FM0000');
    END IF;
    RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_cron_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.index_advisor(query text)
 RETURNS TABLE(startup_cost_before jsonb, startup_cost_after jsonb, total_cost_before jsonb, total_cost_after jsonb, index_statements text[], errors text[])
 LANGUAGE plpgsql
AS $function$
declare
    n_args int;
    prepared_statement_name text = 'index_advisor_working_statement';
    hypopg_schema_name text = (select extnamespace::regnamespace::text from pg_extension where extname = 'hypopg');
    explain_plan_statement text;
    error_message text;
    rec record;
    plan_initial jsonb;
    plan_final jsonb;
    statements text[] = '{}';
begin

    -- Remove comment lines (its common that they contain semicolons)
    query := trim(
        regexp_replace(
            regexp_replace(
                regexp_replace(query,'\/\*.+\*\/', '', 'g'),
            '--[^\r\n]*', ' ', 'g'),
        '\s+', ' ', 'g')
    );

    -- Remove trailing semicolon
    query := regexp_replace(query, ';\s*$', '');

    begin
        -- Disallow multiple statements
        if query ilike '%;%' then
            raise exception 'Query must not contain a semicolon';
        end if;

        -- Hack to support PostgREST because the prepared statement for args incorrectly defaults to text
        query := replace(query, 'WITH pgrst_payload AS (SELECT $1 AS json_data)', 'WITH pgrst_payload AS (SELECT $1::json AS json_data)');

        -- Create a prepared statement for the given query
        deallocate all;
        execute format('prepare %I as %s', prepared_statement_name, query);

        -- Detect how many arguments are present in the prepared statement
        n_args = (
            select
                coalesce(array_length(parameter_types, 1), 0)
            from
                pg_prepared_statements
            where
                name = prepared_statement_name
            limit
                1
        );

        -- Create a SQL statement that can be executed to collect the explain plan
        explain_plan_statement = format(
            'set local plan_cache_mode = force_generic_plan; explain (format json) execute %I%s',
            --'explain (format json) execute %I%s',
            prepared_statement_name,
            case
                when n_args = 0 then ''
                else format(
                    '(%s)', array_to_string(array_fill('null'::text, array[n_args]), ',')
                )
            end
        );

        -- Store the query plan before any new indexes
        execute explain_plan_statement into plan_initial;

        -- Create possible indexes
        for rec in (
            with extension_regclass as (
                select
                    distinct objid as oid
                from
                    pg_catalog.pg_depend
                where
                    deptype = 'e'
            )
            select
                pc.relnamespace::regnamespace::text as schema_name,
                pc.relname as table_name,
                pa.attname as column_name,
                format(
                    'select %I.hypopg_create_index($i$create index on %I.%I(%I)$i$)',
                    hypopg_schema_name,
                    pc.relnamespace::regnamespace::text,
                    pc.relname,
                    pa.attname
                ) hypopg_statement
            from
                pg_catalog.pg_class pc
                join pg_catalog.pg_attribute pa
                    on pc.oid = pa.attrelid
                left join extension_regclass er
                    on pc.oid = er.oid
                left join pg_catalog.pg_index pi
                    on pc.oid = pi.indrelid
                    and (select array_agg(x) from unnest(pi.indkey) v(x)) = array[pa.attnum]
                    and pi.indexprs is null -- ignore expression indexes
                    and pi.indpred is null -- ignore partial indexes
            where
                pc.relnamespace::regnamespace::text not in ( -- ignore schema list
                    'pg_catalog', 'pg_toast', 'information_schema'
                )
                and er.oid is null -- ignore entities owned by extensions
                and pc.relkind in ('r', 'm') -- regular tables, and materialized views
                and pc.relpersistence = 'p' -- permanent tables (not unlogged or temporary)
                and pa.attnum > 0
                and not pa.attisdropped
                and pi.indrelid is null
                and pa.atttypid in (20,16,1082,1184,1114,701,23,21,700,1083,2950,1700,25,18,1042,1043)
            )
            loop
                -- Create the hypothetical index
                execute rec.hypopg_statement;
            end loop;

        /*
        for rec in select * from hypopg()
            loop
                raise notice '%', rec;
            end loop;
        */

        -- Create a prepared statement for the given query
        -- The original prepared statement MUST be dropped because its plan is cached
        execute format('deallocate %I', prepared_statement_name);
        execute format('prepare %I as %s', prepared_statement_name, query);

        -- Store the query plan after new indexes
        execute explain_plan_statement into plan_final;

        --raise notice '%', plan_final;

        -- Idenfity referenced indexes in new plan
        execute format(
            'select
                coalesce(array_agg(hypopg_get_indexdef(indexrelid) order by indrelid, indkey::text), $i${}$i$::text[])
            from
                %I.hypopg()
            where
                %s ilike ($i$%%$i$ || indexname || $i$%%$i$)
            ',
            hypopg_schema_name,
            quote_literal(plan_final)::text
        ) into statements;

        -- Reset all hypothetical indexes
        perform hypopg_reset();

        -- Reset prepared statements
        deallocate all;

        return query values (
            (plan_initial -> 0 -> 'Plan' -> 'Startup Cost'),
            (plan_final -> 0 -> 'Plan' -> 'Startup Cost'),
            (plan_initial -> 0 -> 'Plan' -> 'Total Cost'),
            (plan_final -> 0 -> 'Plan' -> 'Total Cost'),
            statements::text[],
            array[]::text[]
        );
        return;

    exception when others then
        get stacked diagnostics error_message = MESSAGE_TEXT;

        return query values (
            null::jsonb,
            null::jsonb,
            null::jsonb,
            null::jsonb,
            array[]::text[],
            array[error_message]::text[]
        );
        return;
    end;

end;
$function$

CREATE OR REPLACE FUNCTION extensions.set_graphql_placeholder()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$function$

CREATE OR REPLACE FUNCTION public.atualiza_obs_produto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    payload JSONB;
    changes JSONB;
BEGIN
    -- Verifica se houve alteração em alguma das colunas de interesse
    IF (
        NEW.tipo_metal IS DISTINCT FROM OLD.tipo_metal OR
        NEW.peso_precificado IS DISTINCT FROM OLD.peso_precificado OR
        NEW.fornecedor_etl IS DISTINCT FROM OLD.fornecedor_etl OR
        NEW.tipo_de_pedra IS DISTINCT FROM OLD.tipo_de_pedra
    ) THEN
        -- Inicializa o objeto de alterações
        changes := '{}'::jsonb;

        -- Adiciona ao objeto 'changes' apenas as colunas que foram modificadas
        IF NEW.tipo_metal IS DISTINCT FROM OLD.tipo_metal THEN
            changes := changes ||
                jsonb_build_object('tipo_metal', jsonb_build_object('old', OLD.tipo_metal, 'new', NEW.tipo_metal));
        END IF;

        IF NEW.peso_precificado IS DISTINCT FROM OLD.peso_precificado THEN
            changes := changes ||
                jsonb_build_object('peso_precificado', jsonb_build_object('old', OLD.peso_precificado, 'new', NEW.peso_precificado));
        END IF;

        IF NEW.fornecedor_etl IS DISTINCT FROM OLD.fornecedor_etl THEN
            changes := changes ||
                jsonb_build_object('fornecedor_etl', jsonb_build_object('old', OLD.fornecedor_etl, 'new', NEW.fornecedor_etl));
        END IF;

        IF NEW.tipo_de_pedra IS DISTINCT FROM OLD.tipo_de_pedra THEN
            changes := changes ||
                jsonb_build_object('tipo_de_pedra', jsonb_build_object('old', OLD.tipo_de_pedra, 'new', NEW.tipo_de_pedra));
        END IF;

        -- Constrói o payload final com o id_api_produto
        payload := jsonb_build_object(
            'event_type', 'UPDATE',
            'table', TG_TABLE_NAME,
            'schema', TG_TABLE_SCHEMA,
            'record_id', NEW.id_api_produto,
            'timestamp', now(),
            'changes', changes
        );

        -- Envia o payload via POST para o webhook
        PERFORM net.http_post(
            url := 'https://etl.alissonranyel.com.br/webhook/53f71eda-0259-46fc-8431-546577c2654e',
            body := payload,
            headers := '{"Content-Type": "application/json"}'::jsonb
        );
    END IF;

    RETURN NEW;
END;
$function$

